// include/exclude rules, max-parallel limits, and fail-fast configuration

export interface GitHubMatrix {
  include: Record<string, any>[];
  exclude?: Record<string, any>[];
  "fail-fast"?: boolean;
  "max-parallel"?: number;
}

export interface MatrixConfig {
  [key: string]: any;
  include?: Record<string, any>[];
  exclude?: Record<string, any>[];
  failFast?: boolean;
  maxParallel?: number;
  maxSize?: number;
}

function cartesianProduct(arrays: any[][]): any[][] {
  if (arrays.length === 0) return [[]];
  if (arrays.some((arr) => arr.length === 0)) return [];

  return arrays.reduce((acc, arr) =>
    acc.flatMap((item) => arr.map((val) => [...item, val]))
  );
}

function matchesExcludeRule(
  item: Record<string, any>,
  rule: Record<string, any>
): boolean {
  return Object.entries(rule).every(([key, value]) => item[key] === value);
}

function matchesIncludePartially(
  item: Record<string, any>,
  rule: Record<string, any>
): boolean {
  return Object.entries(rule).every(([key, value]) => {
    if (key in item) {
      return item[key] === value;
    }
    return true;
  });
}

export function generateMatrix(config: MatrixConfig): GitHubMatrix {
  // Extract configuration options
  const { include: configInclude = [], exclude: configExclude = [], failFast, maxParallel, maxSize, ...dimensions } = config;

  // Build list of dimension arrays (non-config keys that have array values)
  const dimensionEntries = Object.entries(dimensions).filter(
    ([_, value]) => Array.isArray(value) && value.length > 0
  );

  let combinations: Record<string, any>[] = [];

