    // No dimensions, empty matrix
    combinations = [];
  } else {
    // Get dimension names and values
    const names = dimensionEntries.map(([name]) => name);
    const arrays = dimensionEntries.map(([_, value]) => value);

    // Generate all combinations via Cartesian product
    const products = cartesianProduct(arrays);

    combinations = products.map((values) => {
      const item: Record<string, any> = {};
      names.forEach((name, i) => {
        item[name] = values[i];
      });
      return item;
    });
  }

  // Apply exclude rules
  let filtered = combinations.filter((item) => !configExclude.some((rule) => matchesExcludeRule(item, rule)));

  // Add include items (custom combinations)
  const allItems = [...filtered, ...configInclude];

  // Validate matrix size
  if (maxSize && allItems.length > maxSize) {
    throw new Error(
      `Matrix size ${allItems.length} exceeds maximum allowed size ${maxSize}`
    );
  }

  // Build the output matrix
  const matrix: GitHubMatrix = {
    include: allItems,
  };

  if (failFast !== undefined) {
    matrix["fail-fast"] = failFast;
  }

  if (maxParallel !== undefined) {
    matrix["max-parallel"] = maxParallel;
  }

  return matrix;
}

