  const [first, ...rest] = arrays;
  if (rest.length === 0) {
    return first.map((val) => [val]);
  }

  const restProduct = cartesianProduct(rest);
  return first.flatMap((val) => restProduct.map((combo) => [val, ...combo]));
}

